<script lang="ts">
	/**
	 * /v3-gallery — the Sahoshi visual identity in one page: the Howrah-truss mark, the Sahoshi / সাহসী wordmark,
	 * the lockups and app icon (static/brand, generated by scripts/brand/build_brand.py), the 68 glyphs, every
	 * illustration and artwork file (scripts/brand/build_illustrations.py, build_artwork.py), the reference photos,
	 * the agency marks, the type scale and the colour roles. A developer page in the (v3) group; it polls nothing.
	 */
	import { onMount } from 'svelte';
	import { t } from '$lib/i18n/strings';
	import { readLangCookie } from '$lib/i18n/lang-cookie';
	import { ensureLang } from '$lib/i18n/load';
	import { commandBar } from '$lib/shell/command-bar.svelte';
	import '$lib/v3/packs.v3';
	import Glyph from '$lib/v3/Glyph.svelte';
	import { GLYPHS, GLYPH_COUNT } from '$lib/v3/icons';
	import { EVENT_ART } from '$lib/v3/home/model';
	import '$lib/v3/media/packs.media';
	import { KEY_ART_KINDS, VEHICLE_SHOTS, keyArt } from '$lib/v3/media/art';
	import { PHOTOS } from '$lib/v3/media/photos';
	import { MARKS } from '$lib/v3/media/logos';
	import Cover from '$lib/v3/media/Cover.svelte';
	import VehicleShot from '$lib/v3/media/VehicleShot.svelte';
	import AgencyMark from '$lib/v3/media/AgencyMark.svelte';
	import { v3Bar } from '$lib/v3/shell/v3-bar.svelte';
	import V3Tag from '$lib/v3/ui/V3Tag.svelte';

	const lang = $derived(commandBar.lang);
	const L = (key: string, ...args: unknown[]) => t(lang, key, ...args);

	onMount(() => {
		const c = readLangCookie();
		if (c) {
			commandBar.lang = c;
			void ensureLang(c);
		}
	});

	$effect(() => {
		v3Bar.title = L('v3_gal_title');
		v3Bar.sub = L('v3_gal_lead');
		v3Bar.active = null;
	});

	const BRAND = ['sahoshi-mark', 'sahoshi-mark-solid', 'sahoshi-app-icon', 'favicon', 'sahoshi-lockup', 'sahoshi-wordmark', 'sahoshi-lockup-stacked'];
	const BRAND_DAY = ['sahoshi-mark-day', 'sahoshi-mark-mono', 'sahoshi-lockup-day', 'sahoshi-lockup-mono', 'sahoshi-wordmark-day', 'sahoshi-lockup-stacked-day'];
	const VEHICLES = ['car', 'suv', 'two_wheeler', 'auto_rickshaw', 'bus', 'truck', 'tempo', 'ambulance', 'patrol', 'fire_tender'];
	const AGENCIES = ['police', 'traffic', 'ems', 'fire', 'municipal', 'disaster', 'control_room', 'volunteers'];
	const EMPTY = ['all-clear', 'no-reports', 'assistant', 'offline', 'select-something'];
	const ONBOARDING = ['1-glance', '2-decide', '3-you-decide'];
	const TYPE = [
		['display', 'Display'],
		['title', 'Title'],
		['heading', 'Heading'],
		['sub', 'Sub'],
		['body', 'Body'],
		['meta', 'Meta'],
		['micro', 'Micro'],
	];
	const ROLES: [string, string][] = [
		['decide', 'v3_hero_now'],
		['alert', 'v3_kind_stolen'],
		['ok', 'v3_rep_official'],
		['ai', 'v3_by_ai'],
		['route', 'v3_op_live'],
		['dashed', 'v3_rep_unverified'],
		['ghost', 'v3_rep_news'],
		['brand', 'v3_card_review'],
	];
</script>

<svelte:head><title>{L('v3_gal_title')} · Sahoshi</title></svelte:head>

<div class="gal" data-v3="gallery">
	<section aria-labelledby="g-mark">
		<h2 id="g-mark">{L('v3_gal_mark')}</h2>
		<div class="row">
			{#each BRAND as b (b)}
				<figure class="brand"><img src="/brand/{b}.svg" alt={b} /><figcaption>{b}.svg</figcaption></figure>
			{/each}
			{#each BRAND_DAY as b (b)}
				<figure class="brand day"><img src="/brand/{b}.svg" alt={b} /><figcaption>{b}.svg</figcaption></figure>
			{/each}
		</div>
	</section>

	<section aria-labelledby="g-glyphs">
		<h2 id="g-glyphs">{L('v3_gal_glyphs', GLYPH_COUNT)}</h2>
		<ul class="glyphs">
			{#each Object.keys(GLYPHS) as g (g)}
				<li><Glyph name={g} size={24} /><span>{g}</span></li>
			{/each}
		</ul>
	</section>

	<section aria-labelledby="g-colour">
		<h2 id="g-colour">{L('v3_gal_colour')}</h2>
		<div class="row tags">
			{#each ROLES as [tone, key] (tone)}<V3Tag {tone}>{L(key)}</V3Tag>{/each}
