			{/each}
		</ul>
	</section>

	<section aria-labelledby="g-shots">
		<h2 id="g-shots">{L('v3i_gal_shots')}</h2>
		<ul class="pics">
			{#each VEHICLE_SHOTS as v (v)}
				<li><VehicleShot cls={v} {lang} width={240} /><span>{v}</span></li>
			{/each}
		</ul>
	</section>

	<section aria-labelledby="g-scenes">
		<h2 id="g-scenes">{L('v3i_gal_scenes')}</h2>
