			{/each}
		</ul>
	</section>

	<section aria-labelledby="g-photos">
		<h2 id="g-photos">{L('v3i_gal_photos')}</h2>
		<ul class="pics">
			{#each PHOTOS as p (p.slug)}
				<li><Cover art="" photo={p} alt="" {lang} compact sizes="320px" /><span>{p.title}</span></li>
