		</ul>
	</section>

	<section aria-labelledby="g-marks">
		<h2 id="g-marks">{L('v3i_gal_marks')}</h2>
		<ul class="marks">
			{#each MARKS as mk (mk.key)}
				<li><AgencyMark role={null} mark={mk} {lang} size={44} /><span>{mk.name}</span></li>
			{/each}
		</ul>
		<p class="credit">{L('v3i_marks_credit')}</p>
	</section>

	<section aria-labelledby="g-events">
		<h2 id="g-events">{L('v3_gal_events')}</h2>
		<ul class="art">
			{#each [...EVENT_ART] as e (e)}
				<li><img src="/illustrations/events/{e}.svg" alt="" width="96" height="96" /><span>{e}</span></li>
			{/each}
		</ul>
	</section>

	<section aria-labelledby="g-veh">
		<h2 id="g-veh">{L('v3_gal_vehicles')}</h2>
		<ul class="art">
			{#each VEHICLES as v (v)}
				<li class="veh"><img src="/illustrations/vehicles/{v}.svg" alt="" width="120" height="58" /><span>{v}</span></li>
			{/each}
		</ul>
	</section>

	<section aria-labelledby="g-ag">
		<h2 id="g-ag">{L('v3_gal_agencies')}</h2>
		<ul class="art">
			{#each AGENCIES as a (a)}
				<li><img src="/illustrations/agencies/{a}.svg" alt="" width="64" height="64" /><span>{a}</span></li>
			{/each}
		</ul>
	</section>

	<section aria-labelledby="g-empty">
		<h2 id="g-empty">{L('v3_gal_empty')}</h2>
		<ul class="art wide">
			{#each EMPTY as e (e)}
				<li><img src="/illustrations/empty/{e}.svg" alt="" width="240" height="150" /><span>{e}</span></li>
			{/each}
		</ul>
	</section>

	<section aria-labelledby="g-onb">
		<h2 id="g-onb">{L('v3_gal_onboarding')}</h2>
		<ul class="art wide">
			{#each ONBOARDING as o (o)}
				<li><img src="/illustrations/onboarding/{o}.svg" alt="" width="240" height="150" /><span>{o}</span></li>
			{/each}
		</ul>
	</section>
</div>

